import{_ as i,c as t,o as r,ae as s}from"./chunks/framework.DMK_uHmU.js";const d=JSON.parse('{"title":"User Profile Preferences Guide","description":"","frontmatter":{},"headers":[],"relativePath":"Administration/Manage/Users/user-preferences.md","filePath":"Administration/Manage/Users/user-preferences.md"}'),l={name:"Administration/Manage/Users/user-preferences.md"};function a(n,e,o,u,c,p){return r(),t("div",null,e[0]||(e[0]=[s('<h1 id="user-profile-preferences-guide" tabindex="-1">User Profile Preferences Guide <a class="header-anchor" href="#user-profile-preferences-guide" aria-label="Permalink to &quot;User Profile Preferences Guide&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>The User Profile Preferences component allows administrators to configure personalized settings for each user. These preferences control the user interface appearance, session behavior, default content, and other customization options to optimize the user experience.</p><h2 id="accessing-user-preferences" tabindex="-1">Accessing User Preferences <a class="header-anchor" href="#accessing-user-preferences" aria-label="Permalink to &quot;Accessing User Preferences&quot;">​</a></h2><p>The User Preferences component is accessible to users with specific roles:</p><ul><li>Admin</li><li>Content</li><li>Manager</li></ul><p>To access this component:</p><ol><li>Navigate to a user profile page (<code>/user/profile/[user_id]</code>)</li><li>Click on the &quot;Preferences&quot; tab in the left navigation menu</li></ol><h2 id="user-preferences-interface-overview" tabindex="-1">User Preferences Interface Overview <a class="header-anchor" href="#user-preferences-interface-overview" aria-label="Permalink to &quot;User Preferences Interface Overview&quot;">​</a></h2><p>The User Preferences interface displays a form with multiple setting controls organized in a responsive grid layout. Each preference has a clear label and appropriate input control (toggle switches, dropdown menus, sliders, or radio buttons).</p><p>The header area includes:</p><ul><li>A palette icon indicating customization options</li><li>A &quot;User Preferences&quot; title</li><li>A brief description: &quot;Configure your user preferences&quot;</li></ul><h2 id="available-preference-settings" tabindex="-1">Available Preference Settings <a class="header-anchor" href="#available-preference-settings" aria-label="Permalink to &quot;Available Preference Settings&quot;">​</a></h2><h3 id="language-settings" tabindex="-1">Language Settings <a class="header-anchor" href="#language-settings" aria-label="Permalink to &quot;Language Settings&quot;">​</a></h3><p><strong>Language Dropdown</strong></p><ul><li>Options: English, Spanish, French</li><li>Controls the display language throughout the application</li><li>Affects all text elements, notifications, and system messages</li><li>Default: English</li></ul><h3 id="default-blueprint" tabindex="-1">Default Blueprint <a class="header-anchor" href="#default-blueprint" aria-label="Permalink to &quot;Default Blueprint&quot;">​</a></h3><p><strong>Default AI Assistant Blueprint</strong></p><ul><li>Type: Autocomplete field with dropdown list</li><li>Options: All blueprints marked with <code>ai_blueprint_show_home === true</code></li><li>Purpose: Sets the AI conversation template that loads automatically when a user starts the assistant</li><li>When selected, the specified blueprint will initialize whenever the user opens a new chat session</li><li>When empty (default), users must manually select a blueprint</li></ul><h3 id="security-settings" tabindex="-1">Security Settings <a class="header-anchor" href="#security-settings" aria-label="Permalink to &quot;Security Settings&quot;">​</a></h3><p><strong>Auto Login (Remember Me)</strong></p><ul><li>Type: Toggle switch (On/Off)</li><li>When enabled: User credentials are remembered between browser sessions</li><li>When disabled: User must enter credentials each time they log in</li><li>Default: Enabled</li></ul><h3 id="interface-display-settings" tabindex="-1">Interface Display Settings <a class="header-anchor" href="#interface-display-settings" aria-label="Permalink to &quot;Interface Display Settings&quot;">​</a></h3><p><strong>Control Panel Expanded</strong></p><ul><li>Type: Toggle switch (Yes/No)</li><li>When enabled: The assistant control panel appears expanded by default</li><li>When disabled: The control panel appears collapsed until manually expanded</li><li>Default: Enabled</li><li>Affects the initial state of the control panel when opening the assistant</li></ul><h3 id="session-management" tabindex="-1">Session Management <a class="header-anchor" href="#session-management" aria-label="Permalink to &quot;Session Management&quot;">​</a></h3><p><strong>Session Timeout</strong></p><ul><li>Type: Slider with marked intervals</li><li>Controls how long a user can remain inactive before being automatically logged out</li><li>Options: <ul><li>0: No timeout (session never expires)</li><li>30 minutes</li><li>1 hour</li><li>4 hours</li><li>8 hours</li><li>12 hours</li><li>24 hours</li></ul></li><li>Default: 30 minutes</li><li>For security purposes, this setting determines when to end idle sessions</li></ul><h3 id="theme-settings" tabindex="-1">Theme Settings <a class="header-anchor" href="#theme-settings" aria-label="Permalink to &quot;Theme Settings&quot;">​</a></h3><p><strong>Theme</strong></p><ul><li>Type: Radio button group</li><li>Options: Light, Dark</li><li>Controls the color scheme of the application</li><li>Light: Traditional bright background with dark text</li><li>Dark: Dark background with light text</li><li>Default: Light</li></ul><h2 id="how-preferences-affect-user-experience" tabindex="-1">How Preferences Affect User Experience <a class="header-anchor" href="#how-preferences-affect-user-experience" aria-label="Permalink to &quot;How Preferences Affect User Experience&quot;">​</a></h2><ol><li><p><strong>Theme and Visual Settings</strong></p><ul><li>Directly impact the visual appearance of all screens</li><li>Help accommodate user preferences for light/dark environments</li><li>Can reduce eye strain in different lighting conditions</li></ul></li><li><p><strong>Default Blueprint</strong></p><ul><li>Streamlines workflow by automatically loading frequently used AI conversation templates</li><li>Eliminates the need to select the same blueprint repeatedly</li><li>Particularly useful for users who primarily work with one type of AI interaction</li></ul></li><li><p><strong>Session Timeout</strong></p><ul><li>Balances security with convenience</li><li>Shorter timeouts increase security but may require more frequent logins</li><li>Longer timeouts improve workflow but may pose security risks if workstations are left unattended</li></ul></li><li><p><strong>Language Selection</strong></p><ul><li>Ensures content is presented in the user&#39;s preferred language</li><li>Improves usability for non-native English speakers</li><li>Affects all system text, not user-generated content</li></ul></li></ol><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><p><strong>Setting Session Timeouts</strong></p><ul><li>For shared workstations: Use shorter timeouts (30 minutes to 1 hour)</li><li>For private workstations: Longer timeouts may be acceptable (4-8 hours)</li><li>For high-security environments: Use shorter timeouts regardless of workstation type</li></ul></li><li><p><strong>Default Blueprint Selection</strong></p><ul><li>Choose blueprints that match the user&#39;s primary job function</li><li>For new users, consider leaving this blank until their workflow patterns are established</li><li>Update periodically based on actual usage patterns</li></ul></li><li><p><strong>Theme Configuration</strong></p><ul><li>Consider setting dark mode for users working in low-light environments</li><li>Light mode is typically better for high-light environments and print readability</li><li>Match to organizational branding when possible</li></ul></li><li><p><strong>Control Panel State</strong></p><ul><li>For new users: Set to expanded to increase feature discovery</li><li>For experienced users: Consider collapsed to maximize screen space</li><li>For small screens/mobile users: Collapsed is generally preferred</li></ul></li></ol><hr><p>For additional assistance with user preferences configuration, please contact your system administrator.</p>',37)]))}const f=i(l,[["render",a]]);export{d as __pageData,f as default};
